-- Indexes on every column that points to staff: deleting a staff row checks each of these tables, and without an
-- index that meant reading attendance and marks in full (seconds per delete on the small database).
create index if not exists idx_fk_attendance_record_marked_by on public.attendance_record (marked_by) where marked_by is not null;
create index if not exists idx_fk_mark_entered_by on public.mark (entered_by) where entered_by is not null;
create index if not exists idx_fk_assessment_created_by on public.assessment (created_by) where created_by is not null;
create index if not exists idx_fk_promotion_decided_by on public.promotion (decided_by) where decided_by is not null;
