create index if not exists idx_fk_library_issue_returned_to on public.library_issue (returned_to) where returned_to is not null;
create index if not exists idx_fk_announcement_created_by on public.announcement (created_by) where created_by is not null;
create index if not exists idx_fk_event_created_by on public.event (created_by) where created_by is not null;
create index if not exists idx_fk_position_log_by_staff on public.position_log (by_staff) where by_staff is not null;
